92: <script>
93: /* ============ Configuration ============ */
94: const WORLD_W = 2600;
95: const WORLD_H = 1800;
96: const MAX_CREATURES = 260;
97: const MAX_FOOD = 520;
98: 
99: const BIOMES = [
100:   { key: 'water',  name: 'Eau',        color: '#2364aa', food: { key: 'algae',  energy: 7,  color: '#4fc3f7', rate: 0.40 } },
101:   { key: 'sand',   name: 'Plage',      color: '#d9c28a', food: { key: 'kelp',   energy: 6,  color: '#81c784', rate: 0.12 } },
102:   { key: 'grass',  name: 'Prairie',    color: '#689f38', food: { key: 'grass',  energy: 11, color: '#9ccc65', rate: 0.55 } },
103:   { key: 'forest', name: 'Forêt',      color: '#2e5b2a', food: { key: 'berry',  energy: 24, color: '#b388ff', rate: 0.35 } },
104:   { key: 'mountain', name: 'Montagne', color: '#8d9996', food: { key: null,     energy: 0,  color: '#bdbdbd', rate: 0.0 } },
105:   { key: 'desert', name: 'Désert',     color: '#bcaaa4', food: { key: 'cactus', energy: 5,  color: '#ffd54f', rate: 0.04 } },
106: ];
107: 
108: function biomeAt(wx, wy) {
109:   const n = fBm(wx / 360, wy / 360);
110:   if (n < 0.28) return BIOMES[0];   // water
111:   if (n < 0.38) return BIOMES[1];   // sand
112:   if (n < 0.60) return BIOMES[2];   // grass
113:   if (n < 0.74) return BIOMES[3];   // forest
114:   if (n < 0.84) return BIOMES[4];   // mountain
115:   return BIOMES[5];                 // desert
116: }
117: 
118: /* ============ Simple fractal value noise ============ */
119: function hash2(x, y) {
120:   let n = (x + y * 57.0) | 0;
121:   n = (n << 13) ^ n;
122:   let nn = (n * (n * n * 15731 + 789221) + 1376312589) & 0x7fffffff;
123:   return 1.0 - nn / 1073741824.0;
124: }
125: function lerp(a, b, t) { return a + (b - a) * t; }
126: function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
127: function noise2(x, y) {
128:   const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
129:   const fx = x - Math.floor(x), fy = y - Math.floor(y);
130:   const u = fade(fx), v = fade(fy);
131:   const a = lerp(hash2(X, Y), hash2(X + 1, Y), u);
132:   const b = lerp(hash2(X, Y + 1), hash2(X + 1, Y + 1), u);
133:   return lerp(a, b, v);
134: }
135: function fBm(x, y) {
136:   let v = 0, amp = 0.5, freq = 1;
137:   for (let i = 0; i < 5; i++) { v += amp * noise2(x * freq, y * freq); amp *= 0.5; freq *= 2; }
138:   return v;
139: }
140: 
141: /* ============ DNA / creatures ============ */
142: const DNA_RANGE = {
143:   speed:   [0.5, 4.0],
144:   vision:  [60, 300],
145:   meta:    [0.0005, 0.020],
146:   size:    [3, 16],
147:   agg:     [0, 1],
148:   fert:    [40, 150],
149:   life:    [600, 5000],
150: };
151: 
152: function randomGene(key) {
153:   const [lo, hi] = DNA_RANGE[key];
154:   return lo + Math.random() * (hi - lo);
155: }
156: function randomDNA() {
157:   return {
158:     speed: randomGene('speed'),
159:     vision: randomGene('vision'),
160:     meta: randomGene('meta'),
161:     size: randomGene('size'),
162:     agg: randomGene('agg'),
163:     fert: randomGene('fert'),
164:     life: randomGene('life'),
165:     hue: Math.random() * 360,
166:   };
167: }
168: function mutate(dna) {
169:   return {
170:     speed: clamp(dna.speed   + (Math.random() - 0.5) * 0.9,  DNA_RANGE.speed),
171:     vision: clamp(dna.vision + (Math.random() - 0.5) * 55,   DNA_RANGE.vision),
172:     meta:   clamp(dna.meta   + (Math.random() - 0.5) * 0.004,DNA_RANGE.meta),
173:     size:   clamp(dna.size   + (Math.random() - 0.5) * 2.2,  DNA_RANGE.size),
174:     agg:    clamp(dna.agg    + (Math.random() - 0.5) * 0.25, DNA_RANGE.agg),
175:     fert:   clamp(dna.fert   + (Math.random() - 0.5) * 20,   DNA_RANGE.fert),
176:     life:   clamp(dna.life   + (Math.random() - 0.5) * 500,  DNA_RANGE.life),
177:     hue: (dna.hue + (Math.random() - 0.5) * 60 + 360) % 360,
178:   };
179: }
180: function clamp(v, range) { return Math.max(range[0], Math.min(range[1], v)); }
181: 
182: let nextId = 1;
183: function createCreature(x, y, dna) {
184:   return {
185:     id: nextId++,
186:     x, y, vx: 0, vy: 0,
187:     dna: dna || randomDNA(),
188:     energy: 90,
189:     maxEnergy: 160,
190:     age: 0,
191:     state: 'wander',
192:     target: { x, y },
193:     targetTimer: 60 + Math.random() * 60,
194:     mateCooldown: 0,
195:   };
196: }
197: 
198: /* ============ World state ============ */
199: const canvas = document.getElementById('canvas');
200: const ctx = canvas.getContext('2d', { alpha: false });
201: let width, height;
202: function resize() {
203:   width = canvas.width = innerWidth;
204:   height = canvas.height = innerHeight;
205: }
206: window.addEventListener('resize', resize);
207: resize();
208: 
209: const cam = { x: WORLD_W / 2 - width / 2, y: WORLD_H / 2 - height / 2, zoom: 1 };
210: 
211: const creatures = [];
212: const foods = [];
213: let stats = { births: 0, deaths: 0, frame: 0 };
214: let paused = false;
215: let selectedId = null;
216: 
217: /* Biome offscreen map */
218: const BIO_RES_W = 300, BIO_RES_H = 200;
219: const bioCanvas = document.createElement('canvas');
220: bioCanvas.width = BIO_RES_W; bioCanvas.height = BIO_RES_H;
221: const bioCtx = bioCanvas.getContext('2d');
222: (function drawBiomeMap() {
223:   const data = bioCtx.createImageData(BIO_RES_W, BIO_RES_H);
224:   const d = data.data;
225:   for (let py = 0; py < BIO_RES_H; py++) {
226:     for (let px = 0; px < BIO_RES_W; px++) {
227:       const wx = px / BIO_RES_W * WORLD_W;
228:       const wy = py / BIO_RES_H * WORLD_H;
229:       const b = biomeAt(wx, wy);
230:       const c = hexRgb(b.color);
231:       const i = (py * BIO_RES_W + px) * 4;
232:       d[i] = c[0]; d[i + 1] = c[1]; d[i + 2] = c[2]; d[i + 3] = 255;
233:     }
234:   }
235:   bioCtx.putImageData(data, 0, 0);
236: })();
237: 
238: function hexRgb(hex) {
239:   const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
240:   return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : [0, 0, 0];
241: }
242: 
243: /* Food */
244: function spawnFood(x, y, biomeKey) {
245:   if (foods.length >= MAX_FOOD) return null;
246:   const b = BIOMES.find(b => b.key === biomeKey);
247:   const f = b.food;
248:   foods.push({
249:     x, y,
250:     key: f.key,
251:     energy: f.energy,
252:     color: f.color,
253:     age: 0,
254:   });
255:   return foods[foods.length - 1];
256: }
257: function trySpawnFood() {
258:   if (foods.length >= MAX_FOOD) return;
259:   for (let i = 0; i < 4; i++) {
260:     const wx = Math.random() * WORLD_W;
261:     const wy = Math.random() * WORLD_H;
262:     const b = biomeAt(wx, wy);
263:     if (b.food.key && Math.random() < b.food.rate) {
264:       spawnFood(wx, wy, b.key);
265:       if (foods.length >= MAX_FOOD) return;
266:     }
267:   }
268: }
269: 
270: /* Helpers */
271: function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }
272: function clampCam() {
273:   const sw = width / cam.zoom, sh = height / cam.zoom;
274:   cam.x = Math.max(0, Math.min(WORLD_W - sw, cam.x));
275:   cam.y = Math.max(0, Math.min(WORLD_H - sh, cam.y));
276: }
277: function worldX(sx) { return cam.x + sx / cam.zoom; }
278: function worldY(sy) { return cam.y + sy / cam.zoom; }
279: function screenX(wx) { return (wx - cam.x) * cam.zoom; }
280: function screenY(wy) { return (wy - cam.y) * cam.zoom; }
281: 
282: /* Interaction */
283: let dragging = false, lastSx, lastSy, dragStartSx, dragStartSy, touchId = null;
284: 
285: function pointerDown(sx, sy) {
286:   dragging = true;
287:   lastSx = dragStartSx = sx;
288:   lastSy = dragStartSy = sy;
289: }
290: function pointerMove(sx, sy) {
291:   const dx = sx - lastSx, dy = sy - lastSy;
292:   lastSx = sx; lastSy = sy;
293:   if (dragging) {
294:     cam.x -= dx / cam.zoom;
295:     cam.y -= dy / cam.zoom;
296:     clampCam();
297:   }
298: }
299: function pointerUp() { dragging = false; }
300: function pointerClick(sx, sy) {
301:   if (Math.abs(sx - dragStartSx) < 10 && Math.abs(sy - dragStartSy) < 10) {
302:     selectCreatureAt(sx, sy);
303:   }
304: }
305: 
306: // Mouse
307: canvas.addEventListener('mousedown', e => pointerDown(e.clientX, e.clientY));
308: window.addEventListener('mousemove', e => pointerMove(e.clientX, e.clientY));
309: window.addEventListener('mouseup', pointerUp);
310: canvas.addEventListener('click', e => pointerClick(e.clientX, e.clientY));
311: 
312: // Touch (pan with one finger, tap to inspect)
313: canvas.addEventListener('touchstart', e => {
314:   if (e.touches.length === 1) {
315:     const t = e.touches[0];
316:     touchId = t.identifier;
317:     pointerDown(t.clientX, t.clientY);
318:     e.preventDefault();
319:   }
320: }, { passive: false });
321: canvas.addEventListener('touchmove', e => {
322:   for (const t of e.changedTouches) {
323:     if (t.identifier === touchId) {
324:       pointerMove(t.clientX, t.clientY);
325:       e.preventDefault();
326:       break;
327:     }
328:   }
329: }, { passive: false });
330: canvas.addEventListener('touchend', e => {
331:   for (const t of e.changedTouches) {
332:     if (t.identifier === touchId) {
333:       pointerUp();
334:       pointerClick(t.clientX, t.clientY);
335:       touchId = null;
336:       break;
337:     }
338:   }
339: }, { passive: false });
340: canvas.addEventListener('touchcancel', e => {
341:   for (const t of e.changedTouches) {
342:     if (t.identifier === touchId) { pointerUp(); touchId = null; break; }
343:   }
344: });
345: window.addEventListener('wheel', e => {
346:   e.preventDefault();
347:   const dir = e.deltaY > 0 ? -0.12 : 0.12;
348:   const prev = cam.zoom;
349:   cam.zoom = clamp(cam.zoom * (1 + dir), [0.35, 3.5]);
350:   // zoom toward cursor
351:   const mx = worldX(e.clientX), my = worldY(e.clientY);
352:   cam.x = mx - e.clientX / cam.zoom * prev / prev * 0; // recompute below
353:   // keep cursor over same world point:
354:   cam.x = mx - (e.clientX / width) * (width / cam.zoom);
355:   cam.y = my - (e.clientY / height) * (height / cam.zoom);
356:   clampCam();
357: }, { passive: false });
358: window.addEventListener('keydown', e => {
359:   if (e.code === 'Space') { e.preventDefault(); paused = !paused; document.getElementById('btnPause').textContent = paused ? 'Reprendre' : 'Pause'; }
360:   if (e.code === 'KeyR') resetWorld();
361: });
362: 
363: function selectCreatureAt(sx, sy) {
364:   const wx = worldX(sx), wy = worldY(sy);
365:   let best = null, bestD = 30 / cam.zoom;
366:   for (const c of creatures) {
367:     const d = dist(c, { x: wx, y: wy });
368:     if (d < c.dna.size / cam.zoom + 12 / cam.zoom && d < bestD) { bestD = d; best = c; }
369:   }
370:   selectedId = best ? best.id : null;
371:   updateInspector();
372: }
373: 
374: /* Simulation core */
375: function updateCreature(c) {
376:   const d = c.dna;
377:   const b = biomeAt(c.x, c.y);
378:   const speedMult = b.key === 'water' ? 0.45 : b.key === 'desert' ? 0.85 : 1;
379:   const metaMult = b.key === 'water' ? 1.25 : b.key === 'desert' ? 1.15 : 1;
380: 
381:   c.energy -= d.meta * metaMult * (1 + d.size / 22);
382:   c.age++;
383:   c.mateCooldown = Math.max(0, c.mateCooldown - 1);
384:   if (c.energy <= 0 || c.age > d.life) return 'dead';
385: 
386:   const others = creatures.filter(o => o.id !== c.id && dist(o, c) < d.vision);
387:   const fFood = nearestOf(foods, c, d.vision);
388: 
389:   // --- decisions (depend on DNA + needs) ---
390:   const hungry = c.energy < 55;
391:   const canBreed = c.energy > d.fert && c.mateCooldown <= 0 && creatures.length < MAX_CREATURES;
392: 
393:   if (hungry && fFood) {
394:     c.state = 'seekFood';
395:     c.target = { x: fFood.x, y: fFood.y };
396:   } else if (canBreed) {
397:     const mates = others.filter(o => o.energy > o.dna.fert && o.mateCooldown <= 0);
398:     if (mates.length) {
399:       c.state = 'seekMate';
400:       c.target = { x: mates[0].x, y: mates[0].y };
401:     } else {
402:       c.state = 'wander';
403:     }
404:   } else if (d.agg > 0.5) {
405:     const foes = others.filter(o => o.dna.agg > 0.35);
406:     if (foes.length) {
407:       c.state = 'fight';
408:       c.target = { x: foes[0].x, y: foes[0].y };
409:     } else {
410:       c.state = 'wander';
411:     }
412:   } else {
413:     c.state = 'wander';
414:   }
415: 
416:   // --- movement ---
417:   if (c.state === 'wander') {
418:     if (--c.targetTimer <= 0 || dist(c, c.target) < 14) {
419:       c.target = { x: clamp(c.x + (Math.random() - 0.5) * 300, [0, WORLD_W]), y: clamp(c.y + (Math.random() - 0.5) * 300, [0, WORLD_H]) };
420:       c.targetTimer = 80 + Math.random() * 120;
421:     }
422:     moveToward(c, c.target.x, c.target.y, d.speed * speedMult);
423:   } else {
424:     moveToward(c, c.target.x, c.target.y, d.speed * speedMult);
425:   }
426: 
427:   // --- interactions ---
428:   // eat
429:   for (let i = foods.length - 1; i >= 0; i--) {
430:     const f = foods[i];
431:     if (dist(c, f) < d.size + 5) {
