  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

const saveJpg = (name) => page.evaluate(() => {
  const el = document.querySelector('#viewport canvas');
  return el ? el.toDataURL('image/jpeg', 0.85) : null;
}).then(data => {
  if (!data) throw new Error('no canvas for ' + name);
  const b64 = data.split(',')[1];
  writeFileSync(`${OUT}/${name}.jpg`, Buffer.from(b64, 'base64'));
});

const dispatch = (type, touches) => page.evaluate(({ t, ts }) => {
  const el = document.querySelector('#viewport canvas');
  const mk = ({ id, x, y }) => ({
    identifier: id, target: el, clientX: x, clientY: y, pageX: x, pageY: y,
    screenX: x, screenY: y, radiusX: 1, radiusY: 1, rotationAngle: 0,
    force: 1, altitudeAngle: 0, azimuthAngle: 0,
  });
  const tList = ts.map(m => new Touch(mk(m)));
  const cList = ts.map(m => new Touch(mk(m)));
  el.dispatchEvent(new TouchEvent(t, {
    touches: tList, targetTouches: tList, changedTouches: cList,
    cancelable: true, bubbles: true,
  }));
}, { t: type, ts: touches });
const wait = ms => new Promise(r => setTimeout(r, ms));

await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1500);
await saveJpg('desktop');

