await page.waitForTimeout(500);

// 1) one-finger drag right + up: look right + move forward
await dispatch('touchstart', [{ id: 1, x: 195, y: 560 }]);
await wait(120);
await dispatch('touchmove', [{ id: 1, x: 260, y: 500 }]);
await wait(150);
await dispatch('touchend', [{ id: 1, x: 260, y: 500 }]);
await wait(300);

// 2) tap: inspect creature under finger
await dispatch('touchstart', [{ id: 1, x: 195, y: 560 }]);
await wait(120);
await dispatch('touchend', [{ id: 1, x: 195, y: 560 }]);
await wait(400);

// 3) pinch: fingers move apart -> float higher
await dispatch('touchstart', [{ id: 1, x: 130, y: 560 }, { id: 2, x: 260, y: 560 }]);
await wait(120);
await dispatch('touchmove', [{ id: 1, x: 100, y: 560 }, { id: 2, x: 290, y: 560 }]);
await wait(150);
await dispatch('touchend', [{ id: 1, x: 100, y: 560 }, { id: 2, x: 290, y: 560 }]);
await wait(400);

await saveJpg('mobile');

await page.close();
await browser.close();
if (errors.length) { console.log('ERRORS:', errors.join('; ')); process.exitCode = 1; }
else { console.log('wrote desktop.jpg and mobile.jpg, no errors'); }

